// pixel resolution
vec2 tiles = vec2(2.0, 1.0) * 64.0;
// sub-pixel 
vec2 subTiles = vec2(3.0, 1.0);

vec3 colors[3] = vec3[](
    vec3(1.0, 0.0, 0.0),
    vec3(0.0, 1.0, 0.0),
    vec3(0.0, 0.0, 1.0)
);

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 uv = fragCoord.xy / iResolution.xy;
    // left-half of screen
    if(uv.x < 0.5){
        tiles*=0.5;
        uv.x+=0.5;
    }

    vec2 texUv = (floor(uv*tiles)+0.5) / tiles;
	vec3 texColor = texture(iChannel0, texUv).xyz;

    // pixel uv
	vec2 r = fract(uv * tiles);
    // sub-pixel uv
    r *= subTiles;
    vec3 color = colors[int(r.x)];

    // center align
    r = fract(r) - 0.5;
    // u=u^2, v=v^2
    r = pow(r, vec2(2.0));
    // dot(r,r) = u^4 + v^4  it's an round-rectangle
	float lumin = 1.0 - pow(min(1.0, 20.0 * dot(r, r)), 2.0);

	fragColor = vec4(color*texColor*lumin, 1.0);
}
